// Sample data: two weeks of fake history so every screen has something to
// show on first launch. It's generated by running the *real* session logic,
// so it's also a decent smoke test. Clear it from Program → Settings.

import { allExercises, buildSession, finishSession, nextDay, resetPosition } from './program.js';

const SAMPLE_TMS = {
  'Bench Press': 185, 'Back Squat': 245, 'Barbell Row': 155, 'Deadlift': 315,
};
const SAMPLE_START = {
  'Overhead Press (DB)': 40, 'Incline Press (DB)': 45, 'Triceps Pushdown': 50,
  'Leg Press': 270, 'Split Squat (DB)': 35, 'Leg Extension': 90,
  'Lat Pulldown': 120, 'Face Pull': 40, 'Curl (DB)': 30,
  'Romanian Deadlift': 165, 'Hamstring Curl': 80, 'Back Extension': 0,
};

// Tiny deterministic random generator so the sample is the same every time.
function rng(seed) {
  let x = seed >>> 0;
  return () => {
    x = (x * 1664525 + 1013904223) >>> 0;
    return x / 2 ** 32;
  };
}

// The last `n` dates before today that fall on your lift days, oldest first.
function pastLiftDates(liftDays, n, today = new Date()) {
  const out = [];
  const d = new Date(today);
  d.setHours(18, 0, 0, 0);
  while (out.length < n) {
    d.setDate(d.getDate() - 1);
    if (liftDays.includes(d.getDay())) out.push(new Date(d));
  }
  return out.reverse();
}

export function generateSample(state, today = new Date()) {
  for (const ex of allExercises(state)) {
    if (ex.kind === 'main' && SAMPLE_TMS[ex.name] && !(ex.tm > 0)) {
      ex.tm = SAMPLE_TMS[ex.name];
      ex.tmSource = 'sample';
    }
    if (ex.kind === 'accessory' && ex.name in SAMPLE_START && ex.startWeight == null) {
      ex.startWeight = SAMPLE_START[ex.name];
      ex.startWeightSource = 'sample';
    }
  }
  resetPosition(state);

  const rand = rng(42);
  const days = state.program.days.length;
  const dates = pastLiftDates(state.settings.liftDays, days * 2, today);

  for (const date of dates) {
    const day = nextDay(state);
    state.active = buildSession(state, day.id, date);
    state.active.sample = true;
    for (const ex of state.active.exercises) {
      ex.sets.forEach((set, i) => {
        if (ex.kind === 'main') {
          const last = i === ex.sets.length - 1;
          set.reps += last ? Math.floor(rand() * 3) : (rand() < 0.15 ? 1 : 0);
          if (!set.weight) set.weight = 95;
        } else {
          set.reps = Math.min(ex.repMax, set.reps + Math.floor(rand() * 3));
          if (rand() < 0.15) set.reps = Math.max(ex.repMin - 1, set.reps - 2);
        }
        set.done = true;
      });
    }
    finishSession(state, new Date(date.getTime() + 60 * 60 * 1000));
  }
  state.hasSample = true;
}
